import sys
import math


def spectral_norm_numpy(n):
    import numpy as np

    indices = np.arange(n, dtype=np.float64)
    matrix = np.empty((n, n), dtype=np.float64)

    for i in range(n):
        x = indices + i
        matrix[i, :] = 1.0 / (x * (x + 1.0) * 0.5 + i + 1.0)

    u = np.ones(n, dtype=np.float64)
    for _ in range(10):
        v = matrix.dot(u)
        u = matrix.T.dot(v)

    return math.sqrt(float(np.dot(u, v) / np.dot(v, v)))


def spectral_norm_fallback(n):
    def multiply_a(vector):
        result = [0.0] * n
        for i in range(n):
            denominator = i * (i + 1) * 0.5 + i + 1.0
            increment = i + 1.0
            total = 0.0
            for j in range(n):
                total += vector[j] / denominator
                denominator += increment
                increment += 1.0
            result[i] = total
        return result

    def multiply_at(vector):
        result = [0.0] * n
        for i in range(n):
            denominator = i * (i + 1) * 0.5 + i + 1.0
            increment = i + 1.0
            value = vector[i]
            for j in range(n):
                result[j] += value / denominator
                denominator += increment
                increment += 1.0
        return result

    u = [1.0] * n
    for _ in range(10):
        v = multiply_a(u)
        u = multiply_at(v)

    numerator = 0.0
    denominator = 0.0
    for i in range(n):
        numerator += u[i] * v[i]
        denominator += v[i] * v[i]

    return math.sqrt(numerator / denominator)


def main():
    n = int(sys.argv[1])

    try:
        estimate = spectral_norm_numpy(n)
    except ImportError:
        estimate = spectral_norm_fallback(n)

    print(f"{estimate:.9f}")


if __name__ == "__main__":
    main()
