import sys
import gc


def make_tree(depth):
    if depth == 0:
        return (None, None)
    return (make_tree(depth - 1), make_tree(depth - 1))


def node_count(depth):
    return (1 << (depth + 1)) - 1


def main():
    n = int(sys.argv[1])
    gc.disable()

    stretch_depth = n + 1
    stretch = make_tree(stretch_depth)
    print(f"stretch tree of depth {stretch_depth}\t check: {node_count(stretch_depth)}")
    del stretch

    long_lived = make_tree(n)

    for depth in range(4, n + 1, 2):
        trees = 1 << (n - depth + 4)
        checksum = trees * node_count(depth)

        for _ in range(trees):
            tree = make_tree(depth)
            del tree

        print(f"{trees}\t trees of depth {depth}\t check: {checksum}")

    print(f"long lived tree of depth {n}\t check: {node_count(n)}")
    del long_lived


if __name__ == "__main__":
    main()
